class Router
  def initialize(rules)
    @mutex, @rules = Mutex.new, rules.freeze
  end
  def publish(rules)                                # control channel
    @mutex.synchronize { @rules = rules.freeze }
  end
  def route(msg)
    rules = @rules                                  # one snapshot per message
    (rules[msg.key] || method(:dead_letter)).call(msg)
  end
end

